var calc_output = [];

//user inputs
var score = parseFloat(post) + parseFloat(level) + parseFloat(bmi) + parseFloat(age);

//interpretation
var rec, risk, risk_grp;
if(score<2){
	rec = 'Can safely discontinue oral anticoagulation';
    risk = '3'
    risk_grp = 'Low'
}else{
	rec = 'Continue oral anticoagulation';
    risk = '8'
    risk_grp = 'High'
}

//results
calc_output.push({
    name: 'mini',
    value: score,
    value_text: 'points',
    message: rec
});
calc_output.push({
    name: '4005_HERDOO2 Rule_result (score)',
    value: score,
    value_text: 'points',
    message: 'HERDOO2 Score'
});
calc_output.push({
    name: '4005_HERDOO2 Rule_result (risk)',
    value: risk,
    value_text: '%',
    message: 'Risk of recurrent major VTE per 100 patient years'
});
calc_output.push({
    name: '4005_HERDOO2 Rule_interpretation',
    value: risk_grp,
    value_text: 'risk',
    message: rec
});
